// Tests for the unmanaged helpers in overrides.go (not generated by Speakeasy).

package flagutil

import "testing"

func TestFriendlyDescriptionStripsBackticks(t *testing.T) {
	got := friendlyDescription("Whether you are depositing into or withdrawing from the given Earn `venue`. (options: DEPOSIT, WITHDRAW) [required]")
	want := "Whether you are depositing into or withdrawing from the given Earn venue. (options: DEPOSIT, WITHDRAW) [required]"
	if got != want {
		t.Fatalf("friendlyDescription() = %q, want %q", got, want)
	}
}

func TestFriendlyDescriptionRewritesNumberOrString(t *testing.T) {
	got := friendlyDescription("JSON value (one of: number | string)")
	if got != `Decimal amount, as a number or quoted string (e.g. 100 or "1.5").` {
		t.Fatalf("unexpected rewrite: %q", got)
	}
}

func TestUsageAllowsValue(t *testing.T) {
	outputUsage := "Specify the output format. Options: pretty, json, yaml, table, toon."
	chainUsage := "The chain to use. (options: base, ethereum, arbitrum) [required]"
	cases := []struct {
		usage, value string
		want         bool
	}{
		{outputUsage, "json", true},
		{outputUsage, "toon", true},
		{outputUsage, "tvl_usd", false},
		{outputUsage, "", false},
		{chainUsage, "base", true},
		{chainUsage, "solana", false},
		{"Filter by symbol.", "json", false},
	}
	for _, c := range cases {
		if got := usageAllowsValue(c.usage, c.value); got != c.want {
			t.Errorf("usageAllowsValue(%q, %q) = %v, want %v", c.usage, c.value, got, c.want)
		}
	}
}
